/*
 * A296693  Numbers whose base-3 digits d(m), d(m-1), ... d(0) have #(rises) <
 *          #(falls); see Comments.
 * https://oeis.org/A296693
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 107, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A296693: numbers whose base‑3 digits d(m)…d(0) have
   #(rises) < #(falls).  The sequence is generated by scanning
   integers and storing those that satisfy the condition. */
#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>

/* Return true when the base‑3 representation of x has more falls than rises. */
static bool has_more_falls(seq_t x)
{
    /* Zero or one digit has no rises or falls. */
    if (x < (seq_t)1)
        return false;          /* not a natural number */

    /* Collect the digits LSB → MSB. */
    int digits[128];           /* enough for any 64‑bit value in base 3 */
    int len = 0;
    seq_t t = x;
    while (t > (seq_t)0) {
        digits[len++] = (int)(t % (seq_t)3);
        t      /= (seq_t)3;
    }
    if (len <= 1)
        return false;          /* only one digit → no rises/falls */

    int rises = 0, falls = 0;
    /* Compare from most significant to least (digits[len‑1] … digits[0]). */
    for (int i = len - 1; i > 0; --i) {
        int cur  = digits[i];
        int next = digits[i - 1];
        if (cur < next)
            ++rises;
        else if (cur > next)
            ++falls;
    }
    return rises < falls;
}

/* Cache of previously computed terms.  Static state allows calls in any order. */
static seq_t *cache      = NULL;
static size_t cache_size = 0;   /* number of terms stored */
static size_t cache_cap  = 0;   /* capacity of cache array */
static uint64_t scanned   = 0;  /* highest integer examined so far */

static void grow_cache(size_t needed)
{
    if (needed <= cache_cap)
        return;
    size_t new_cap = (cache_cap == 0) ? 16 : cache_cap * 2;
    while (new_cap < needed)
        new_cap *= 2;
    seq_t *new_cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!new_cache) {
        /* Allocation failed – terminate with an empty sequence. */
        abort();
    }
    cache      = new_cache;
    cache_cap  = new_cap;
}

/* Main sequence function. */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;   /* undefined for n=0, but return 0 */

    /* Ensure cache contains at least n terms. */
    while (cache_size < (size_t)n) {
        scanned++;

        if (has_more_falls(scanned)) {
            grow_cache(cache_size + 1);
            cache[cache_size++] = (seq_t)scanned;
        }
    }
    return cache[n - 1];
}
